  1	/* ============================================================
  2	   views/orchestrator.js — Orchestrator View
  3	   MCP Server Dashboard SPA — Phase 5 (WP-011)
  4	
  5	   Renders the top-level orchestrator view:
  6	     Section A: plan path input + preflight + start
  7	     Section B: live run queue table with polling
  8	     Footer: CLI reference card
  9	
 10	   Depends on: API (api-client.js), Router (router.js),
 11	               OrchestratorWidgets (js/orchestrator-widgets.js),
 12	               escapeHtml (utils.js)
 13	   ============================================================ */
 14	
 15	// Module-scoped log-preview cleanup registry.
 16	// Each renderOrchestrator() call drains this array before creating new widgets.
 17	var _orchLogPreviewCleanups = [];
 18	
 19	/**
 20	 * Top-level orchestrator view entry point.
 21	 * Called by Router.dispatch() when the user navigates to #/orchestrator.
 22	 *
 23	 * @param {HTMLElement} app - The root #app container element.
 24	 */
 25	function renderOrchestrator(app) {
 26	  // 1. Drain log preview cleanup callbacks from the previous render.
 27	  _orchLogPreviewCleanups.forEach(function (fn) { try { fn(); } catch (_) {} });
 28	  _orchLogPreviewCleanups = [];
 29	
 30	  // 2. Render the static skeleton.
 31	  app.innerHTML =
 32	    '<h1 class="section-title">Orchestrator</h1>' +
 33	
 34	    '<section class="orch-section">' +
 35	      '<h2 class="orch-section-title">Start New Run</h2>' +
 36	      '<div class="orch-start-panel">' +
 37	        '<div class="orch-plan-input-row">' +
 38	          '<input type="text" id="orch-plan-path" class="orch-plan-input"' +
 39	            ' placeholder="Absolute path to plan.md…" autocomplete="off">' +
 40	          '<button type="button" id="orch-preflight-btn" class="btn btn-secondary">' +
 41	            'Run Preflight' +
 42	          '</button>' +
 43	          '<button type="button" id="orch-start-btn" class="btn btn-primary" disabled>' +
 44	            'Start Run' +
 45	          '</button>' +
 46	        '</div>' +
 47	        '<div id="orch-preflight-results"></div>' +
 48	      '</div>' +
 49	    '</section>' +
 50	
 51	    '<section class="orch-section">' +
 52	      '<h2 class="orch-section-title">Run Queue</h2>' +
 53	      '<div id="orch-queue-container"><p class="text-muted">Loading queue…</p></div>' +
 54	    '</section>' +
 55	
 56	    '<section class="orch-section orch-cli-section">' +
 57	      OrchestratorWidgets.renderCliReference() +
 58	    '</section>';
 59	
 60	  // 3. Bind UI references.
 61	  var preflightBtn = document.getElementById('orch-preflight-btn');
 62	  var startBtn     = document.getElementById('orch-start-btn');
 63	  var planInput    = document.getElementById('orch-plan-path');
 64	  var resultsEl    = document.getElementById('orch-preflight-results');
 65	
 66	  var allChecksPassed = false;
 67	
 68	  // 4. Render preflight results checklist.
 69	  function renderPreflightResults(checks) {
 70	    if (!checks || !checks.length) {
 71	      resultsEl.innerHTML = '';
 72	      allChecksPassed = false;
 73	      startBtn.disabled = true;
 74	      return;
 75	    }
 76	    allChecksPassed = checks.every(function (c) { return c.pass; });
 77	    startBtn.disabled = !allChecksPassed;
 78	    if (!startBtn.disabled) startBtn.textContent = 'Start Run';
 79	
 80	    var html = '<ul class="preflight-list">';
 81	    checks.forEach(function (c) {
 82	      var cls = c.pass ? 'preflight-pass' : 'preflight-fail';
 83	      html += '<li class="preflight-check ' + cls + '">';
 84	      html += '<span class="preflight-icon">' + (c.pass ? '✓' : '✗') + '</span>';
 85	      html += ' <strong>' + escapeHtml(c.name) + '</strong>: ' + escapeHtml(c.detail);
 86	      if (!c.pass && c.fix) {
 87	        html += ' <span class="preflight-fix">Fix: <code>' + escapeHtml(c.fix) + '</code></span>';
 88	      }
 89	      html += '</li>';
 90	    });
 91	    html += '</ul>';
 92	    resultsEl.innerHTML = html;
 93	  }
 94	
 95	  // 5. Preflight button handler.
 96	  preflightBtn.addEventListener('click', function () {
 97	    var planPath = planInput.value.trim();
 98	    if (!planPath) { window.alert('Please enter a plan path.'); return; }
 99	
100	    preflightBtn.disabled = true;

  1	/**
  2	 * Queue reading internals for the orchestrator run queue (WP-B extraction).
  3	 *
  4	 * Reads `.run-queue.json`, enriches each raw entry with computed lifecycle
  5	 * state and JSONL progress data, and returns the result as `QueueEntry[]`.
  6	 *
  7	 * This module is read-only with respect to the queue file and all other files.
  8	 *
  9	 * Exports beyond `getQueue()`:
 10	 *   - `readQueueFile` — used by `checkNoConflict` in `orchestrator-manager.ts`.
 11	 *   - `isProcessAlive` — used by queue-mutation functions in `orchestrator-manager.ts`.
 12	 *   - `getProjectLedgerStatus` — used by `killQueueEntry`/`dismissQueueEntry`
 13	 *     in `orchestrator-manager.ts`.
 14	 */
 15	
 16	import { readFile } from 'node:fs/promises';
 17	import { join } from 'node:path';
 18	
 19	import { QUEUE_FILENAME, type RawQueueEntry, type QueueEntry } from './types.js';
 20	import { resolveProgress } from './resolve-progress.js';
 21	import { computeEffectiveStatus } from './compute-effective-status.js';
 22	
 23	// ---------------------------------------------------------------------------
 24	// PID alive check
 25	// ---------------------------------------------------------------------------
 26	
 27	/**
 28	 * Returns `true` if the process with `pid` exists on this machine.
 29	 *
 30	 * Uses `process.kill(pid, 0)` which is a zero-signal check — it only
 31	 * verifies the process exists and does not actually deliver any signal.
 32	 *
 33	 * Exported for use by queue-mutation functions in `orchestrator-manager.ts`.
 34	 */
 35	export function isProcessAlive(pid: number): boolean {
 36	  try {
 37	    process.kill(pid, 0);
 38	    return true;
 39	  } catch {
 40	    return false;
 41	  }
 42	}
 43	
 44	// ---------------------------------------------------------------------------
 45	// Queue file reader
 46	// ---------------------------------------------------------------------------
 47	
 48	/**
 49	 * Reads and parses `<logsDir>/.run-queue.json`.
 50	 * Returns `[]` on any I/O or parse error — fail-safe.
 51	 * Never writes to the queue file.
 52	 *
 53	 * Exported for use by `checkNoConflict` in `orchestrator-manager.ts`.
 54	 */
 55	export async function readQueueFile(logsDir: string): Promise<RawQueueEntry[]> {
 56	  const queuePath = join(logsDir, QUEUE_FILENAME);
 57	  let raw: string;
 58	  try {
 59	    raw = await readFile(queuePath, 'utf-8');
 60	  } catch {
 61	    return [];
 62	  }
 63	  try {
 64	    const data: unknown = JSON.parse(raw);
 65	    if (!Array.isArray(data)) return [];
 66	    return data.filter(isRawQueueEntry);
 67	  } catch {
 68	    return [];
 69	  }
 70	}
 71	
 72	function isRawQueueEntry(entry: unknown): entry is RawQueueEntry {
 73	  if (typeof entry !== 'object' || entry === null) return false;
 74	  const e = entry as Record<string, unknown>;
 75	  return (
 76	    typeof e['id'] === 'string' &&
 77	    typeof e['pid'] === 'number' && Number.isInteger(e['pid']) && (e['pid'] as number) > 0 &&
 78	    typeof e['planPath'] === 'string' &&
 79	    typeof e['expectedSlug'] === 'string' && (e['expectedSlug'] as string).length > 0 &&
 80	    typeof e['startedAt'] === 'string'
 81	  );
 82	}
 83	
 84	// ---------------------------------------------------------------------------
 85	// Project ledger check
 86	// ---------------------------------------------------------------------------
 87	
 88	/**
 89	 * Returns whether the project identified by `slug` has a ledger entry and
 90	 * whether synthesis has been generated for it.
 91	 *
 92	 * Fail-safe: any I/O or parse error returns `{ exists: false, synthesisGenerated: false }`.
 93	 *
 94	 * Exported for use by `killQueueEntry`/`dismissQueueEntry` in `orchestrator-manager.ts`.
 95	 *
 96	 * @param ledgerRoot - Absolute path to the ledger root directory.
 97	 * @param slug       - Project slug (e.g. `2026-05-05-my-feature`).
 98	 * @returns An object with two fields:
 99	 *   - `exists` — `true` when `<ledgerRoot>/<slug>/project-ledger.json` is present and
100	 *     readable; `false` on any I/O error or when the file does not exist.

101	 *   - `synthesisGenerated` — `true` when the ledger's `synthesis_generated` field equals
102	 *     `true`; `false` when the file is absent, unreadable, or the field is falsy.
103	 */
104	export async function getProjectLedgerStatus(
105	  ledgerRoot: string,
106	  slug: string,
107	): Promise<{ exists: boolean; synthesisGenerated: boolean }> {
108	  const projectLedgerPath = join(ledgerRoot, slug, 'project-ledger.json');
109	  let raw: string;
110	  try {
111	    raw = await readFile(projectLedgerPath, 'utf-8');
112	  } catch {
113	    return { exists: false, synthesisGenerated: false };
114	  }
115	  try {
116	    const data = JSON.parse(raw) as Record<string, unknown>;
117	    return {
118	      exists: true,
119	      synthesisGenerated: data['synthesis_generated'] === true,
120	    };
121	  } catch {
122	    return { exists: true, synthesisGenerated: false };
123	  }
124	}
125	
126	// ---------------------------------------------------------------------------
127	// Public API
128	// ---------------------------------------------------------------------------
129	
130	/**
131	 * Reads the shared orchestrator run queue and returns all active entries
132	 * enriched with computed lifecycle state and JSONL progress summaries.
133	 *
134	 * Entries for completed projects (`synthesis_generated === true`) are
135	 * automatically excluded from the result.
136	 *
137	 * This function is read-only: it never writes to the queue file or any
138	 * other file on disk.
139	 *
140	 * @param params.logsDir    - Absolute path to `orchestrator/logs/`.
141	 * @param params.ledgerRoot - Absolute path to the central ledger root.
142	 * @returns Enriched queue entries, excluding completed runs.
143	 */
144	export async function getQueue(params: {
145	  logsDir: string;
146	  ledgerRoot: string;
147	}): Promise<QueueEntry[]> {
148	  const { logsDir, ledgerRoot } = params;
149	
150	  const rawEntries = await readQueueFile(logsDir);
151	  if (rawEntries.length === 0) return [];
152	
153	  const enriched = await Promise.all(
154	    rawEntries.map(async (entry) => {
155	      const [projectStatus, progressResult] = await Promise.all([
156	        getProjectLedgerStatus(ledgerRoot, entry.expectedSlug),
157	        resolveProgress(logsDir, entry.expectedSlug),
158	      ]);
159	
160	      const { exists: projectExists, synthesisGenerated } = projectStatus;
161	      const alive = isProcessAlive(entry.pid);
162	
163	      // Compute effective status per AC-2 through AC-5.
164	      const effectiveStatus = computeEffectiveStatus(alive, projectExists, progressResult.hasStageActivity);
165	
166	      // AC-6: exclude entries whose project has completed synthesis.
