255	  /** Injects DOM-based action buttons and toggle listeners into the rendered
256	   *  table. Must be called after container.innerHTML has been set.
257	   *
258	   *  Branch priority (dismissibility-first):
259	   *    1. pending  → Kill button   (process is still running)
260	   *    2. dead     → Dismiss button (process has exited without completing)
261	   *    3. projectExists → View Project link (project ledger is on disk)
262	   *  The dead branch precedes the projectExists branch so that a dead entry
263	   *  that also has a known project slug always renders Dismiss, not View Project. */
264	  function _bindQueueActions(container, entries) {
265	    entries.forEach(function (entry) {
266	      var id     = entry.id || '';
267	      var status = entry.effectiveStatus || 'pending';
268	      var cell   = container.querySelector('[data-actions-for="' + id + '"]');
269	      if (!cell) return;
270	
271	      if (status === 'pending') {
272	        cell.appendChild(OrchestratorWidgets.renderKillButton(id, function () {
273	          delete expandedIds[id];
274	          refreshQueue();
275	        }));
276	      } else if (status === 'dead') {
277	        cell.appendChild(OrchestratorWidgets.renderDismissButton(id, function () {
278	          delete expandedIds[id];
279	          refreshQueue();
280	        }));
281	      } else if (entry.projectExists === true && entry.expectedSlug) {
