296	      });
297	    });
298	  }
299	
300	  /** Starts log previews for all currently expanded rows and registers their
301	   *  cleanup callbacks in _orchLogPreviewCleanups. */
302	  function _mountLogPreviews(container, entries) {
303	    entries.forEach(function (entry) {
304	      var id = entry.id || '';
305	      if (!expandedIds[id] || !entry.logFilename || !entry.expectedSlug) return;
306	      var previewEl = document.getElementById('orch-log-' + id);
307	      if (!previewEl) return;
308	      var cleanup = OrchestratorWidgets.renderLogPreview(
309	        previewEl,
310	        entry.expectedSlug,
311	        entry.logFilename,
312	      );
313	      _orchLogPreviewCleanups.push(cleanup);
314	    });
315	  }
316	
317	  // ---- renderQueueTable coordinator ----------------------------------------
318	
319	  function renderQueueTable(container, entries) {
320	    // Save viewport scroll position before replacing innerHTML — the document
321	    // viewport is the scrolling context (not the container, which has no
322	    // overflow CSS), so window.scrollY is the correct save/restore target.
323	    var savedScrollY = window.scrollY;
324	
325	    if (!entries.length) {
326	      container.innerHTML = '<p class="text-muted orch-empty-queue">No active runs in the queue.</p>';
327	      return;
328	    }
329	
330	    _clearSuccessBanner();
331	    container.innerHTML = _buildQueueHtml(entries);
332	    _bindQueueActions(container, entries);
333	    _mountLogPreviews(container, entries);
334	
335	    // Restore scroll position after all DOM manipulation is complete.
336	    // Must be the last statement so intermediate DOM mutations do not
337	    // interfere with the restored position.
338	    window.scrollTo(0, savedScrollY);
339	  }
340	
341	  // 8. Kick off the first queue fetch and register the polling interval.
342	  refreshQueue();
343	  Router._setPolling(refreshQueue, 5000);
344	}
