350	/** Returns the final path segment (filename or folder name). */
351	function _orchBasename(path) {
352	  var parts = String(path).replace(/\\/g, '/').split('/');
353	  return parts[parts.length - 1] || path;
354	}
355	
356	/** Human-readable label for an effectiveStatus value. */
357	function _orchStatusLabel(status) {
358	  if (status === 'started') return 'Started';
359	  if (status === 'dead')    return 'Dead';
360	  return 'Pending';
361	}
362	
363	/** Formats elapsed time from an ISO start timestamp. */
364	function _orchElapsed(startedAt) {
365	  if (!startedAt) return '—';
366	  try {
367	    var diff = Date.now() - new Date(startedAt).getTime();
368	    if (isNaN(diff) || diff < 0) return '—';
369	    var secs = Math.round(diff / 1000);
370	    if (secs < 60)  return secs + 's';
371	    var mins = Math.floor(secs / 60);
372	    if (mins < 60)  return mins + 'm ' + (secs % 60) + 's';
373	    return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
374	  } catch (_) {
375	    return '—';
376	  }
377	}

